(async () => {
  try {
    const res = await fetch('https://sdp-prem-prod.premier-league-prod.pulselive.com/api/v2/matches?compSeasId=0&gameweek=1&page=0&pageSize=40', {
      headers: {
        'Accept': 'application/json',
      },
      credentials: 'include',
    });
    const text = await res.text();
    return { status: res.status, url: res.url, ok: res.ok, text: text.slice(0, 5000) };
  } catch (e) {
    return { error: String(e) };
  }
})()

